ate['doc_type']??'certificate')))?></small></td><td><?=e($certificate['created_at'])?></td><td><?=e($certificate['scan_state'])?></td><td><?=e($certificate['review_state'])?></td><td><a href="student.php?certificate=<?=(int)$certificate['id']?>">Download</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if(!in_array($application['status'],['Admitted','Rejected','Withdrawn'],true)&&count($certs)<10): ?><form method="post" enctype="multipart/form-data"><?=csrf()?><input type="hidden" name="action" value="upload_certificate"><input type="hidden" name="application_id" value="<?=(int)$application['id']?>"><input type="hidden" name="version" value="<?=(int)$application['version']?>"><div class="u-form"><label>Certificate file<input type="file" name="certificate" accept=".pdf,.jpg,.jpeg,.png" required></label><button class="u-btn solid">Upload certificate</button></div></form><?php endif; ?></section><?php endif; ?><?php if(in_array($application['status'],['Changes requested','Revision'],true)): ?><section class="u-card"><h2>Correct and resubmit</h2><p>Read the office's requested changes below. Email, institute, course and quoted fee cannot be changed here. You can also attach missing documents in step 3.</p><?=spUploadForm('revise_application')?><div class="u-form"><input type="hidden" name="application_id" value="<?=(int)$application['id']?>"><input type="hidden" name="version" value="<?=(int)$application['version']?>"><?php applicationFormFields($data,$application['consent_notice'],'revise'); ?></div></form></section><?php endif; ?><?php if(!in_array($application['status'],['Admitted','Rejected','Withdrawn'],true)): ?><section class="u-card"><details><summary>Withdraw this application</summary><?=spForm('withdraw_application')?><input type="hidden" name="application_id" value="<?=(int)$application['id']?>"><input type="hidden" name="version" value="<?=(int)$application['version']?>"><div class="u-form"><label>Reason<textarea name="reason" maxle